const URL_WITH_QUERY_RE = /\bhttps?:\/\/[^\s"'<>]+/gi;
const SECRETISH_QUERY_KEY_RE =
  /(^|[-_])(api[-_]?key|key|token|secret|password|session|auth|signature|sig)([-_]|$)/i;

/** Replaces exact resolved-secret values with a placeholder. */
export function redactSecretsOnly(text: string, secrets: Array<string | undefined>): string {
  let redacted = text;
  for (const secret of secrets) {
    const value = secret?.trim();
    if (!value) continue;
    redacted = redacted.split(value).join("[redacted]");
  }
  return redacted;
}

/** Recursively redacts exact known secret strings in JSON-compatible values. */
export function redactJsonSecrets(value: unknown, secrets: Array<string | undefined>): unknown {
  if (typeof value === "string") {
    return redactSecretsOnly(value, secrets);
  }
  if (Array.isArray(value)) {
    return value.map((item) => redactJsonSecrets(item, secrets));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [key, redactJsonSecrets(item, secrets)]),
    );
  }
  return value;
}

/**
 * Redacts a URL for the evidence log: masks resolved secrets and the values
 * of declared or secret-ish query parameters, but preserves the path and
 * non-secret query params so repros stay meaningful.
 */
export function redactUrl(
  rawUrl: string,
  secrets: Array<string | undefined>,
  credentialQueryKeys: Iterable<string> = [],
): string {
  const secretRedacted = redactSecretsOnly(rawUrl, secrets);
  try {
    const url = new URL(secretRedacted);
    const credentialKeys = new Set(credentialQueryKeys);
    for (const key of [...url.searchParams.keys()]) {
      if (credentialKeys.has(key) || SECRETISH_QUERY_KEY_RE.test(key)) {
        url.searchParams.set(key, "[redacted]");
      }
    }
    url.hash = "";
    return url.toString();
  } catch {
    return secretRedacted;
  }
}

/** Redacts exact secrets and strips query strings from surfaced URLs. */
export function redactMessage(message: string, secrets: Array<string | undefined>): string {
  const redacted = redactSecretsOnly(message, secrets);

  return redacted.replace(URL_WITH_QUERY_RE, (candidate) => {
    try {
      const url = new URL(candidate);
      url.search = "";
      url.hash = "";
      return url.toString();
    } catch {
      return candidate;
    }
  });
}

/** Converts unknown errors to redacted user-facing messages. */
export function toRedactedError(error: unknown, secrets: Array<string | undefined>): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(redactMessage(message, secrets), { cause: error });
}

const AUTH_SCHEME_RE = /\b(?:Bearer|Basic|Digest|Negotiate)\s+\S{8,}/i;
const HIGH_ENTROPY_TOKEN_RE = /[A-Za-z0-9+/_.=-]{20,}/g;
const MIN_TOKEN_ENTROPY_BITS = 3.2;

/** Shannon entropy per character of a string, in bits. */
function shannonEntropy(value: string): number {
  const counts = new Map<string, number>();
  for (const char of value) counts.set(char, (counts.get(char) ?? 0) + 1);
  let bits = 0;
  for (const count of counts.values()) {
    const p = count / value.length;
    bits -= p * Math.log2(p);
  }
  return bits;
}

/**
 * Heuristically decides whether an already-redacted value still looks like it
 * carries a live credential. Scout only redacts secrets it can identify (env
 * references and secret-ish header/query/body names), so a literal token pasted
 * into an arbitrary header would otherwise leak into output and artifacts. A
 * surviving auth scheme or high-entropy token is a strong tell.
 */
export function looksLikeUnredactedSecret(value: string): boolean {
  if (value.includes("[redacted]")) return false;
  if (AUTH_SCHEME_RE.test(value)) return true;
  for (const token of value.match(HIGH_ENTROPY_TOKEN_RE) ?? []) {
    if (shannonEntropy(token) >= MIN_TOKEN_ENTROPY_BITS) return true;
  }
  return false;
}

import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { log } from "@clack/prompts";
import { stringifyJson } from "./output.js";
import { isInteractive } from "./utils.js";

const AGENTS_MD_START = "<!-- TESTERARMY-SCOUT:START -->";
const AGENTS_MD_END = "<!-- TESTERARMY-SCOUT:END -->";
const SKILL_NAME = "scout";
const BUNDLED_SKILL_PATH = fileURLToPath(new URL("../skills/scout/SKILL.md", import.meta.url));

export type AgentInitOptions = {
  json?: boolean;
  skipSkillInstall?: boolean;
  skipAgentsMd?: boolean;
  cwd?: string;
  skillSource?: string;
};

type AgentInitResult = {
  success: boolean;
  skill: {
    name: string;
    path: string;
    installed: boolean;
    skipped: boolean;
  };
  agentsMd: {
    path: string;
    written: boolean;
    skipped: boolean;
  };
  nextSteps: string[];
};

/** Installs the bundled scout skill and AGENTS.md discovery hints into a repo. */
export async function runAgentInitCommand(options: AgentInitOptions): Promise<void> {
  const cwd = options.cwd ?? process.cwd();
  const install = options.skipSkillInstall
    ? skippedSkillInstall(cwd)
    : installBundledSkill(cwd, options.skillSource ?? BUNDLED_SKILL_PATH);
  const agentsMd = options.skipAgentsMd ? skippedAgentsMd(cwd) : writeLocalAgentsMd(cwd);
  const result: AgentInitResult = {
    success: true,
    skill: install,
    agentsMd,
    nextSteps: [
      "Confirm authorized hosts, endpoints, methods, identities, rate, budget, and test window.",
      "Run `scout init <spec> --base-url <url>`, then orient with `scout endpoints --json` and `scout schema ... --json`.",
      "Preview a filtered `scout sweep --dry-run`, execute it, then use `scout call`/`scout fuzz` and `scout report`.",
    ],
  };

  if (options.json || !isInteractive()) {
    console.log(stringifyJson(result));
    return;
  }

  if (install.installed) log.success(`Installed bundled ${SKILL_NAME} skill at ${install.path}.`);
  else log.info("Skipped skill installation.");
  if (agentsMd.written) log.success(`Updated ${agentsMd.path} with scout agent guidance.`);
  else if (agentsMd.skipped) log.info("Skipped AGENTS.md update.");
  log.info("Next: confirm authorized scope, then run `scout init <spec> --base-url <url>`.");
}

function installBundledSkill(cwd: string, source: string): AgentInitResult["skill"] {
  const path = join(cwd, ".agents", "skills", SKILL_NAME, "SKILL.md");
  mkdirSync(dirname(path), { recursive: true });
  copyFileSync(source, path);
  return { name: SKILL_NAME, path, installed: true, skipped: false };
}

function skippedSkillInstall(cwd: string): AgentInitResult["skill"] {
  return {
    name: SKILL_NAME,
    path: join(cwd, ".agents", "skills", SKILL_NAME, "SKILL.md"),
    installed: false,
    skipped: true,
  };
}

function skippedAgentsMd(cwd: string): AgentInitResult["agentsMd"] {
  return { path: join(cwd, "AGENTS.md"), written: false, skipped: true };
}

function writeLocalAgentsMd(cwd: string): AgentInitResult["agentsMd"] {
  const path = join(cwd, "AGENTS.md");
  const existing = existsSync(path) ? readFileSync(path, "utf-8") : null;
  const next = mergeScoutAgentsMd(existing);
  if (existing !== next) writeFileSync(path, next);
  return { path, written: existing !== next, skipped: false };
}

/** Merges the scout guidance block into AGENTS.md between stable markers. */
export function mergeScoutAgentsMd(existing: string | null): string {
  const block = buildScoutAgentsBlock();
  if (!existing || existing.trim() === "") return `# AGENTS.md\n\n${block}\n`;

  const startIdx = existing.indexOf(AGENTS_MD_START);
  if (startIdx !== -1) {
    const endIdx = existing.indexOf(AGENTS_MD_END, startIdx + AGENTS_MD_START.length);
    let before = existing.slice(0, startIdx);
    if (before.length > 0 && !before.endsWith("\n")) before += "\n";
    const after = endIdx === -1 ? "\n" : existing.slice(endIdx + AGENTS_MD_END.length);
    return `${before}${block}${after}`;
  }

  return `${existing.replace(/\s+$/, "")}\n\n${block}\n`;
}

function buildScoutAgentsBlock(): string {
  return [
    AGENTS_MD_START,
    "## Scout - API exploration",
    "",
    "This project can use scout to explore and test authorized APIs from an OpenAPI spec.",
    "",
    "- **Skill:** use the local `scout` skill for the full workflow; refresh it with `scout agent init`.",
    "- **Authorize:** confirm host, endpoints, methods, identities/tenants, test data, rate, budget, and test window before requests.",
    "- **Start:** `scout init <spec> --base-url <url>` starts an isolated run; `scout status --json` shows local state.",
    "- **Orient:** use `scout endpoints --json` and `scout schema <method> <path> --json`.",
    "- **Plan:** preview traffic with a filtered `scout sweep --dry-run --json`.",
    "- **Explore:** `scout call <method> <path> --json` only executes documented operations by default.",
    "- **Fuzz:** preview with `scout fuzz <method> <path> --dry-run --json`; execute only with mutation authorization and cleanup.",
    "- **Report:** validate candidate findings, then finish with `scout report --ci`.",
    AGENTS_MD_END,
  ].join("\n");
}

import { beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  isInteractive: vi.fn(),
  loadProjectConfig: vi.fn(),
  loadSessionState: vi.fn(),
  readFindings: vi.fn(),
  resolvePolicy: vi.fn(),
  sessionExists: vi.fn(),
}));

vi.mock("./utils.js", () => ({ isInteractive: mocks.isInteractive }));
vi.mock("./project-config.js", () => ({
  loadProjectConfig: mocks.loadProjectConfig,
  resolvePolicy: mocks.resolvePolicy,
}));
vi.mock("./session-store.js", () => ({
  loadSessionState: mocks.loadSessionState,
  sessionExists: mocks.sessionExists,
}));
vi.mock("./findings.js", () => ({ readFindings: mocks.readFindings }));

const { runStatusCommand } = await import("./status-command.js");

describe("status command", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mocks.isInteractive.mockReturnValue(false);
    vi.spyOn(console, "log").mockImplementation(() => {});
  });

  it("reports no local run without account state", async () => {
    mocks.sessionExists.mockReturnValue(false);
    await runStatusCommand({ json: true });
    expect(JSON.parse(vi.mocked(console.log).mock.calls[0]?.[0] as string)).toEqual({
      session: { active: false },
    });
  });

  it("reports local run policy and provenance", async () => {
    mocks.sessionExists.mockReturnValue(true);
    mocks.loadSessionState.mockReturnValue({
      runId: "run-1",
      createdAt: "2026-01-01T00:00:00.000Z",
      specSource: "openapi.json",
      specHash: "hash",
      requestCount: 3,
    });
    mocks.loadProjectConfig.mockReturnValue({
      config: { spec: "openapi.json", baseUrl: "https://api.test" },
      path: "scout.json",
    });
    mocks.resolvePolicy.mockReturnValue({ allowMutations: false, rateLimit: 2, budget: 20 });
    mocks.readFindings.mockReturnValue([{}]);

    await runStatusCommand({ json: true });

    expect(JSON.parse(vi.mocked(console.log).mock.calls[0]?.[0] as string)).toMatchObject({
      session: {
        active: true,
        runId: "run-1",
        baseUrl: "https://api.test",
        requestsUsed: 3,
        requestBudget: 20,
        budgetRemaining: 17,
        rateLimit: 2,
        findings: 1,
      },
    });
  });
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { initSession } from "./session-store.js";

describe("reset command", () => {
  let cwd: string;
  let originalCwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-reset-"));
    originalCwd = process.cwd();
    process.chdir(cwd);
  });

  afterEach(() => {
    vi.restoreAllMocks();
    process.chdir(originalCwd);
    rmSync(cwd, { recursive: true, force: true });
  });

  it("prints the new run ID as JSON", async () => {
    const first = initSession(
      {
        spec: { openapi: "3.1.0", info: { title: "Test", version: "1" }, paths: {} },
        source: "test",
        hash: "hash",
        title: "Test",
        version: "1",
        specVersion: "3.1.0",
        converted: false,
        dereferenced: true,
        warnings: [],
      },
      cwd,
    );
    const output = vi.spyOn(console, "log").mockImplementation(() => {});
    const { runResetCommand } = await import("./reset-command.js");

    runResetCommand({ json: true });

    expect(JSON.parse(output.mock.calls[0]?.[0] as string).runId).not.toBe(first.runId);
  });
});

import { describe, expect, it } from "vitest";
import { capDepth } from "./schema-command.js";

describe("capDepth", () => {
  it("keeps shallow structures intact", () => {
    const input = { a: 1, b: { c: 2 } };
    const { value, truncated } = capDepth(input, 6);
    expect(value).toEqual(input);
    expect(truncated).toBe(false);
  });

  it("truncates objects beyond the max depth", () => {
    const input = { l1: { l2: { l3: { l4: "deep" } } } };
    const { value, truncated } = capDepth(input, 2);
    expect(truncated).toBe(true);
    expect(value).toEqual({ l1: { l2: "[…object — use --full]" } });
  });

  it("truncates arrays beyond the max depth", () => {
    const { value, truncated } = capDepth({ items: [[["deep"]]] }, 2);
    expect(truncated).toBe(true);
    expect(value).toEqual({ items: ["[…array — use --full]"] });
  });

  it("does not truncate empty objects or arrays at the boundary", () => {
    const { truncated } = capDepth({ a: {}, b: [] }, 1);
    expect(truncated).toBe(false);
  });

  it("preserves primitives", () => {
    expect(capDepth("x", 0).value).toBe("x");
    expect(capDepth(42, 0).value).toBe(42);
    expect(capDepth(null, 0).value).toBe(null);
  });
});

import { mkdirSync, mkdtempSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { ScoutError } from "./errors.js";
import { hasInterpolation, interpolateVars, loadVars, saveVars, setVar } from "./session-vars.js";

describe("session vars store", () => {
  let cwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-vars-"));
    mkdirSync(join(cwd, ".scout"));
    writeFileSync(
      join(cwd, ".scout", "state.json"),
      JSON.stringify({
        runId: "test-run",
        specSource: "test",
        specHash: "test",
        createdAt: new Date(0).toISOString(),
        requestCount: 0,
      }),
    );
  });

  afterEach(() => {
    rmSync(cwd, { recursive: true, force: true });
  });

  it("returns an empty map when nothing is captured", () => {
    expect(loadVars(cwd)).toEqual({});
  });

  it("persists and reloads variables", () => {
    saveVars({ projectId: "p1" }, cwd);
    expect(loadVars(cwd)).toEqual({ projectId: "p1" });
    expect(statSync(join(cwd, ".scout", "vars.json")).mode & 0o777).toBe(0o600);
  });

  it("sets a single variable while preserving existing ones", () => {
    setVar("a", "1", cwd);
    setVar("b", "2", cwd);
    expect(loadVars(cwd)).toEqual({ a: "1", b: "2" });
  });

  it("throws a useful error for a corrupt vars file", () => {
    writeFileSync(join(cwd, ".scout", "vars.json"), "{broken");
    expect(() => loadVars(cwd)).toThrowError(/Failed to parse session variables/);
  });

  it("rejects non-string variable values", () => {
    writeFileSync(join(cwd, ".scout", "vars.json"), JSON.stringify({ id: 123 }));
    expect(() => loadVars(cwd)).toThrowError(/expected string values/);
  });

  it("requires an active session before writing", () => {
    rmSync(join(cwd, ".scout", "state.json"));
    expect(() => saveVars({ projectId: "p1" }, cwd)).toThrowError(/No scout session/);
    expect(() => setVar("projectId", "p1", cwd)).toThrowError(/No scout session/);
  });
});

describe("interpolateVars", () => {
  it("replaces known references", () => {
    expect(interpolateVars("/v1/projects/{{id}}", { id: "p1" })).toBe("/v1/projects/p1");
  });

  it("replaces multiple references and tolerates whitespace", () => {
    expect(interpolateVars("{{a}}-{{ b }}", { a: "x", b: "y" })).toBe("x-y");
  });

  it("leaves text without references untouched", () => {
    expect(interpolateVars("/v1/projects", {})).toBe("/v1/projects");
  });

  it("throws a helpful error for unknown references", () => {
    expect(() => interpolateVars("{{missing}}", {})).toThrow(ScoutError);
  });
});

describe("hasInterpolation", () => {
  it("detects references regardless of prior regex state", () => {
    expect(hasInterpolation("{{a}}")).toBe(true);
    expect(hasInterpolation("{{a}}")).toBe(true);
    expect(hasInterpolation("plain")).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { extractPath, stringifyExtracted } from "./json-path.js";

describe("extractPath", () => {
  const body = {
    project: { id: "p1", name: "demo" },
    items: [{ id: "a" }, { id: "b" }],
    count: 2,
    nested: { list: [{ tags: ["x", "y"] }] },
  };

  it("reads dotted object paths", () => {
    expect(extractPath(body, "project.id")).toBe("p1");
  });

  it("reads array indices with bracket and dot notation", () => {
    expect(extractPath(body, "items[0].id")).toBe("a");
    expect(extractPath(body, "items.1.id")).toBe("b");
  });

  it("reads deeply nested array values", () => {
    expect(extractPath(body, "nested.list[0].tags[1]")).toBe("y");
  });

  it("returns undefined for missing keys or out-of-range indices", () => {
    expect(extractPath(body, "project.missing")).toBeUndefined();
    expect(extractPath(body, "items[9].id")).toBeUndefined();
    expect(extractPath(body, "count.nope")).toBeUndefined();
  });

  it("returns undefined when descending into null", () => {
    expect(extractPath({ a: null }, "a.b")).toBeUndefined();
  });
});

describe("stringifyExtracted", () => {
  it("passes primitives through", () => {
    expect(stringifyExtracted("abc")).toBe("abc");
    expect(stringifyExtracted(42)).toBe("42");
    expect(stringifyExtracted(true)).toBe("true");
  });

  it("serializes objects and arrays as JSON", () => {
    expect(stringifyExtracted({ a: 1 })).toBe('{"a":1}');
    expect(stringifyExtracted([1, 2])).toBe("[1,2]");
  });

  it("renders null and undefined as an empty string", () => {
    expect(stringifyExtracted(null)).toBe("");
    expect(stringifyExtracted(undefined)).toBe("");
  });
});

import { describe, expect, it } from "vitest";
import { isJsonOutputRequested, ScoutError, toJsonErrorEnvelope } from "./errors.js";

describe("CLI error envelopes", () => {
  it("detects JSON mode from argv", () => {
    expect(isJsonOutputRequested(["node", "scout", "status", "--json"])).toBe(true);
    expect(isJsonOutputRequested(["node", "scout", "status"])).toBe(false);
  });

  it("formats API status errors", () => {
    const error = new Error("Forbidden") as Error & { statusCode: number };
    error.statusCode = 403;

    expect(toJsonErrorEnvelope(error, 2)).toEqual({
      success: false,
      error: {
        code: "AUTH_FAILED",
        message:
          "Target API authentication failed. Check the selected auth profile or configured headers.",
        hint: "Check the target API credentials configured in scout.json and retry.",
        statusCode: 403,
      },
      exitCode: 2,
    });
  });

  it("carries explicit code and hint from ScoutError", () => {
    const error = new ScoutError("No scout session in this directory.", {
      code: "NO_SESSION",
      hint: "Run `scout init <spec>` first.",
    });

    expect(toJsonErrorEnvelope(error, 2)).toEqual({
      success: false,
      error: {
        code: "NO_SESSION",
        message: "No scout session in this directory.",
        hint: "Run `scout init <spec>` first.",
      },
      exitCode: 2,
    });
  });

  it("extracts status code from nested causes", () => {
    const inner = new Error("upstream") as Error & { statusCode: number };
    inner.statusCode = 429;
    const outer = new Error("wrapped", { cause: inner });

    expect(toJsonErrorEnvelope(outer, 2).error.statusCode).toBe(429);
  });
});

import { describe, expect, it } from "vitest";
import { computeCoverage } from "./coverage.js";
import type { RequestRecord } from "./session-store.js";
import type { SpecOperation } from "./spec-loader.js";

function op(method: SpecOperation["method"], path: string): SpecOperation {
  return {
    method,
    path,
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    responses: {},
  };
}

function record(operation: string, schemaValid: RequestRecord["schemaValid"]): RequestRecord {
  return {
    id: "x",
    timestamp: "now",
    source: "call",
    operation,
    method: operation.split(" ")[0] ?? "GET",
    url: "https://x",
    status: 200,
    latencyMs: 1,
    schemaValid,
    requestHeaders: {},
  };
}

describe("computeCoverage", () => {
  const operations = [op("get", "/pets"), op("post", "/pets"), op("get", "/pets/{id}")];

  it("counts unexercised operations", () => {
    const summary = computeCoverage(operations, []);
    expect(summary.totalOperations).toBe(3);
    expect(summary.exercised).toBe(0);
    expect(summary.coveragePercent).toBe(0);
    expect(summary.requestTotals).toEqual({ recorded: 0, matched: 0, probes: 0 });
    expect(summary.untouched).toHaveLength(3);
  });

  it("marks called vs validated", () => {
    const summary = computeCoverage(operations, [
      record("GET /pets", true),
      record("POST /pets", "unknown"),
    ]);

    expect(summary.exercised).toBe(2);
    expect(summary.validated).toBe(1);
    expect(summary.coveragePercent).toBe(67);
    expect(summary.requestTotals).toEqual({ recorded: 2, matched: 2, probes: 0 });
    expect(summary.operations.find((o) => o.operation === "GET /pets")?.state).toBe("validated");
    expect(summary.operations.find((o) => o.operation === "GET /pets")).toMatchObject({
      controlCalls: 1,
      negativeCalls: 0,
      statuses: [200],
    });
    expect(summary.operations.find((o) => o.operation === "POST /pets")?.state).toBe("called");
    expect(summary.untouched).toEqual(["GET /pets/{id}"]);
  });

  it("does not treat negative probes as validated controls", () => {
    const negative = { ...record("GET /pets", true), source: "fuzz" as const };
    const summary = computeCoverage(operations, [negative]);
    expect(summary.operations.find((o) => o.operation === "GET /pets")).toMatchObject({
      state: "called",
      controlCalls: 0,
      negativeCalls: 1,
    });
  });
});

import { describe, expect, it } from "vitest";
import {
  filterOperations,
  parseMethod,
  resolveOperationsOrThrow,
  scopeOperations,
} from "./operation-filter.js";
import type { SpecOperation } from "./spec-loader.js";

function op(overrides: Partial<SpecOperation>): SpecOperation {
  return {
    method: "get",
    path: "/",
    tags: [],
    deprecated: false,
    secured: false,
    authParameters: [],
    parameters: [],
    responses: {},
    ...overrides,
  };
}

const operations: SpecOperation[] = [
  op({ method: "get", path: "/pets", tags: ["pets"], summary: "list pets" }),
  op({ method: "post", path: "/pets", tags: ["pets"], summary: "create pet" }),
  op({ method: "get", path: "/admin/stats", tags: ["admin"], summary: "stats" }),
];

describe("filterOperations", () => {
  it("filters by tag", () => {
    expect(filterOperations(operations, { tag: "admin" })).toHaveLength(1);
  });

  it("filters by method", () => {
    expect(filterOperations(operations, { method: "post" })).toHaveLength(1);
  });

  it("filters by path glob", () => {
    expect(filterOperations(operations, { path: "/admin/**" })).toHaveLength(1);
  });

  it("filters by free-text search", () => {
    expect(filterOperations(operations, { search: "create" })).toHaveLength(1);
  });

  it("combines filters", () => {
    expect(filterOperations(operations, { tag: "pets", method: "get" })).toHaveLength(1);
  });
});

describe("parseMethod", () => {
  it("accepts known methods case-insensitively", () => {
    expect(parseMethod("POST")).toBe("post");
  });

  it("rejects unknown methods", () => {
    expect(() => parseMethod("connectx")).toThrow(/--method must be one of/);
  });
});

describe("scopeOperations", () => {
  it("applies method and OpenAPI path scope", () => {
    expect(
      scopeOperations(operations, { allowedMethods: ["GET"], allowedPaths: ["/pets"] }).map(
        (operation) => `${operation.method} ${operation.path}`,
      ),
    ).toEqual(["get /pets"]);
  });
});

describe("resolveOperationsOrThrow", () => {
  it("throws VALIDATION_ERROR when explicit filters match nothing", () => {
    expect(() => resolveOperationsOrThrow(operations, { tag: "ghost" })).toThrow();
  });

  it("does not throw on empty result without filters", () => {
    expect(resolveOperationsOrThrow([], {})).toEqual([]);
  });
});

