describe("deterministic findings", () => {
  it("deduplicates repeated mechanical findings and preserves lifecycle status", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const input = {
        source: "sweep" as const,
        severity: "high" as const,
        category: "auth" as const,
        endpoint: "GET /admin",
        title: "Potential auth bypass",
        status: "candidate" as const,
      };
      const first = createFinding(input);
      const repeated = createFinding(input);

      expect(repeated.id).toBe(first.id);
      expect(appendFinding(first, cwd).created).toBe(true);
      expect(appendFinding(repeated, cwd).created).toBe(false);
      expect(readFindings(cwd)).toHaveLength(1);

      expect(updateFindingStatus(first.id, "dismissed", cwd).status).toBe("dismissed");
      expect(appendFinding(repeated, cwd).finding.status).toBe("dismissed");
      expect(readFindings(cwd)).toHaveLength(1);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("collapses the same contract issue across probe kinds (different repro)", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const base = {
        source: "sweep" as const,
        severity: "medium" as const,
        category: "contract-violation" as const,
        endpoint: "GET /v1/ai-gateway/rules",
        title: "Undocumented status 404",
      };
      // Same finding seen on happy-path, no-auth, invalid-auth probes.
      const a = createFinding({ ...base, repro: "scout call GET /v1/ai-gateway/rules" });
      const b = createFinding({ ...base, repro: "scout call GET /v1/ai-gateway/rules --no-auth" });
      const c = createFinding({
        ...base,
        repro: "scout call GET /v1/ai-gateway/rules --invalid-auth",
      });

      expect(b.id).toBe(a.id);
      expect(c.id).toBe(a.id);
      expect(appendFinding(a, cwd).created).toBe(true);
      expect(appendFinding(b, cwd).created).toBe(false);
      expect(appendFinding(c, cwd).created).toBe(false);
      expect(readFindings(cwd)).toHaveLength(1);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("records and clears a dismiss reason across transitions", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      const finding = createFinding({
        source: "sweep",
        severity: "high",
        category: "auth",
        endpoint: "GET /admin",
        title: "Potential auth bypass",
      });
      appendFinding(finding, cwd);

      const dismissed = updateFindingStatus(finding.id, "dismissed", cwd, undefined, "known WIP");
      expect(dismissed.dismissReason).toBe("known WIP");

      const reconfirmed = updateFindingStatus(finding.id, "confirmed", cwd);
      expect(reconfirmed.dismissReason).toBeUndefined();
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });

  it("throws when lifecycle id is unknown", () => {
    const cwd = mkdtempSync(join(tmpdir(), "scout-findings-"));
    mkdirSync(join(cwd, ".scout"));
    try {
      expect(() => updateFindingStatus("missing", "confirmed", cwd)).toThrow(/not found/);
    } finally {
      rmSync(cwd, { recursive: true, force: true });
    }
  });
});

import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  appendFindingRecordForRun,
  appendRequestRecordForRun,
  incrementRequestCount,
  initSession,
  loadCachedSpec,
  loadSessionState,
  reserveRequest,
  resetSession,
} from "./session-store.js";
import type { LoadedSpec } from "./spec-loader.js";

const loadedSpec: LoadedSpec = {
  spec: { openapi: "3.1.0", info: { title: "Test", version: "1.0.0" }, paths: {} },
  source: "openapi.json",
  hash: "spec-hash",
  title: "Test",
  version: "1.0.0",
  specVersion: "3.1.0",
  converted: false,
  dereferenced: true,
  warnings: [],
};

describe("session runs", () => {
  let cwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-session-"));
  });

  afterEach(() => {
    rmSync(cwd, { recursive: true, force: true });
  });

  it("starts an isolated run on every init", () => {
    const first = initSession(loadedSpec, cwd);
    incrementRequestCount(cwd);
    for (const filename of ["requests.jsonl", "findings.jsonl", "vars.json"]) {
      writeFileSync(join(cwd, ".scout", filename), "old run\n");
    }

    const second = initSession(loadedSpec, cwd);

    expect(second.runId).not.toBe(first.runId);
    expect(loadSessionState(cwd)).toEqual(second);
    expect(second.requestCount).toBe(0);
    for (const filename of ["requests.jsonl", "findings.jsonl", "vars.json"]) {
      expect(existsSync(join(cwd, ".scout", filename))).toBe(false);
    }
  });

  it("resets artifacts without replacing the cached spec", () => {
    const first = initSession(loadedSpec, cwd);
    const cached = loadCachedSpec(cwd);
    writeFileSync(join(cwd, ".scout", "findings.jsonl"), "old run\n");

    const second = resetSession(cwd);

    expect(second.runId).not.toBe(first.runId);
    expect(second.requestCount).toBe(0);
    expect(loadCachedSpec(cwd)).toEqual(cached);
    expect(existsSync(join(cwd, ".scout", "findings.jsonl"))).toBe(false);
  });

  it("reserves budget atomically and returns the owning run", () => {
    const run = initSession(loadedSpec, cwd);
    expect(reserveRequest(1, cwd)).toMatchObject({ runId: run.runId, requestCount: 1 });
    expect(() => reserveRequest(1, cwd)).toThrow(/budget exhausted/);
  });

  it("rejects request and finding writes owned by a previous run", () => {
    const first = initSession(loadedSpec, cwd);
    resetSession(cwd);

    expect(() =>
      appendRequestRecordForRun(
        {
          id: "request",
          runId: first.runId,
          timestamp: "now",
          source: "call",
          operation: "GET /pets",
          method: "GET",
          url: "https://api.test/pets",
          status: 200,
          latencyMs: 1,
          schemaValid: true,
          requestHeaders: {},
        },
        first.runId,
        cwd,
      ),
    ).toThrow(/active run changed/);
    expect(() => appendFindingRecordForRun("{}", first.runId, cwd)).toThrow(/active run changed/);
    expect(existsSync(join(cwd, ".scout", "requests.jsonl"))).toBe(false);
    expect(existsSync(join(cwd, ".scout", "findings.jsonl"))).toBe(false);
  });
});

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { loadProjectConfig } from "./project-config.js";
import { loadSessionState } from "./session-store.js";

/** Creates a minimal OpenAPI spec with a distinct default server. */
const spec = (title: string, server: string) => ({
  openapi: "3.1.0",
  info: { title, version: "1.0.0" },
  servers: [{ url: server }],
  paths: {},
});

describe("init run isolation", () => {
  let cwd: string;
  let originalCwd: string;

  beforeEach(() => {
    cwd = mkdtempSync(join(tmpdir(), "scout-init-"));
    originalCwd = process.cwd();
    process.chdir(cwd);
    writeFileSync(join(cwd, "first.json"), JSON.stringify(spec("First", "https://first.test")));
    writeFileSync(join(cwd, "second.json"), JSON.stringify(spec("Second", "https://second.test")));
    vi.spyOn(console, "log").mockImplementation(() => {});
  });

  afterEach(() => {
    vi.restoreAllMocks();
    process.chdir(originalCwd);
    rmSync(cwd, { recursive: true, force: true });
  });

  it("does not inherit target or safety config when a new spec is supplied", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", {
      baseUrl: "https://override.test",
      header: ["X-Test: old"],
      allowMutations: true,
      json: true,
    });

    await runInitCommand("second.json", { json: true });

    expect(loadProjectConfig()?.config).toEqual({
      $schema: "https://tester.army/scout.schema.json",
      spec: "second.json",
      baseUrl: "https://second.test",
      policy: { allowMutations: false },
    });
  });

  it("preserves config but starts a clean run during bare hydration", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", {
      header: ["X-Test: kept"],
      json: true,
    });
    const firstRun = loadSessionState();
    writeFileSync(join(cwd, ".scout", "requests.jsonl"), "old run\n");
    const configBefore = readFileSync(join(cwd, "scout.json"), "utf-8");

    await runInitCommand(undefined, { json: true });

    const hydratedResult = JSON.parse(vi.mocked(console.log).mock.calls.at(-1)?.[0] as string) as {
      runId: string;
    };
    expect(hydratedResult.runId).not.toBe(firstRun.runId);
    expect(loadSessionState().runId).toBe(hydratedResult.runId);
    expect(loadSessionState().requestCount).toBe(0);
    expect(readFileSync(join(cwd, "scout.json"), "utf-8")).toBe(configBefore);
    expect(() => readFileSync(join(cwd, ".scout", "requests.jsonl"), "utf-8")).toThrow();
  });

  it("does not persist empty scope arrays when only one scope flag is provided", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", { allowMethod: ["get"], json: true });

    expect(loadProjectConfig()?.config.policy).toEqual({
      allowMutations: false,
      allowedMethods: ["GET"],
    });
  });

  it("persists --max-spec-mb as maxSpecBytes so hydration reuses the cap", async () => {
    const { runInitCommand } = await import("./init-command.js");
    await runInitCommand("first.json", { maxSpecMb: 40, json: true });

    expect(loadProjectConfig()?.config.maxSpecBytes).toBe(40 * 1024 * 1024);
  });
});

describe("resolveMaxSpecBytes", () => {
  it("converts MiB to bytes and prefers the flag over persisted config", async () => {
    const { resolveMaxSpecBytes } = await import("./init-command.js");
    expect(resolveMaxSpecBytes({ maxSpecMb: 10 }, { baseUrl: "x", maxSpecBytes: 999 })).toBe(
      10 * 1024 * 1024,
    );
    expect(resolveMaxSpecBytes({}, { baseUrl: "x", maxSpecBytes: 999 })).toBe(999);
    expect(resolveMaxSpecBytes({}, undefined)).toBeUndefined();
  });

  it("rejects a value above the hard ceiling", async () => {
    const { resolveMaxSpecBytes } = await import("./init-command.js");
    expect(() => resolveMaxSpecBytes({ maxSpecMb: 1000 }, undefined)).toThrowError(
      /between 1 and 100/,
    );
  });
});

import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  detectLiteralSecretHeaders,
  loadProjectConfig,
  resolvePolicy,
  writeProjectConfig,
  type ScoutProjectConfig,
} from "./project-config.js";

let dir: string;

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "scout-cfg-"));
  vi.unstubAllEnvs();
});

afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
  vi.unstubAllEnvs();
});

const base: ScoutProjectConfig = {
  spec: "openapi.json",
  baseUrl: "https://api.example.com",
  policy: { allowMutations: false },
};

describe("detectLiteralSecretHeaders", () => {
  it("flags secret-like headers without env references", () => {
    expect(detectLiteralSecretHeaders({ Authorization: "Bearer abc123", "X-Trace": "on" })).toEqual(
      ["Authorization"],
    );
  });

  it("allows env references", () => {
    expect(detectLiteralSecretHeaders({ Authorization: "Bearer $TOKEN" })).toEqual([]);
  });
});

describe("write + load round trip", () => {
  it("writes and reloads a valid config", () => {
    const { path } = writeProjectConfig(base, { cwd: dir });
    const loaded = loadProjectConfig({ cwd: dir });
    expect(loaded?.path).toBe(path);
    expect(loaded?.config.baseUrl).toBe("https://api.example.com");
  });

  it("returns null when no config exists", () => {
    expect(loadProjectConfig({ cwd: dir })).toBeNull();
  });

  it("rejects unknown keys", () => {
    writeFileSync(join(dir, "scout.json"), JSON.stringify({ ...base, bogus: true }));
    expect(() => loadProjectConfig({ cwd: dir })).toThrow(/Invalid scout.json/);
  });

  it("rejects literal secrets in CI", () => {
    vi.stubEnv("CI", "1");
    writeFileSync(
      join(dir, "scout.json"),
      JSON.stringify({ ...base, headers: { Authorization: "Bearer literal-token" } }),
    );
    expect(() => loadProjectConfig({ cwd: dir })).toThrow(/literal secrets/);
  });

  it("rejects literal auth profile values in CI", () => {
    vi.stubEnv("CI", "1");
    writeFileSync(
      join(dir, "scout.json"),
      JSON.stringify({
        ...base,
        authProfiles: { admin: { cookies: { session: "literal-token" } } },
      }),
    );
    expect(() => loadProjectConfig({ cwd: dir })).toThrow(/authProfiles\.admin\.cookies\.session/);
  });

  it("accepts environment references in auth profiles", () => {
    writeFileSync(
      join(dir, "scout.json"),
      JSON.stringify({
        ...base,
        authProfiles: {
          admin: {
            headers: { Authorization: "Bearer $ADMIN_TOKEN" },
            query: { api_key: "$ADMIN_KEY" },
            cookies: { session: "$ADMIN_SESSION" },
